/**
 * Date utility functions
 */

/**
 * Get date N days ago (time set to 00:00:00)
 */
export function getDaysAgo(days: number): Date {
  const date = new Date()
  date.setDate(date.getDate() - days)
  date.setHours(0, 0, 0, 0)
  return date
}

/**
 * Get end of today (23:59:59)
 */
export function getEndOfToday(): Date {
  const date = new Date()
  date.setHours(23, 59, 59, 999)
  return date
}

/**
 * Convert date to millisecond timestamp
 */
export function dateToTimestamp(date: Date): number {
  return date.getTime()
}

/**
 * Format date as YYYY-MM-DD
 */
export function formatDate(date: Date): string {
  const year = date.getFullYear()
  const month = String(date.getMonth() + 1).padStart(2, '0')
  const day = String(date.getDate()).padStart(2, '0')
  return `${year}-${month}-${day}`
}

/**
 * Parse date from YYYY-MM-DD string
 */
export function parseDate(dateStr: string): Date {
  const date = new Date(dateStr)
  date.setHours(0, 0, 0, 0)
  return date
}

/**
 * Generate all dates (YYYY-MM-DD) between startTime and endTime inclusive, in local timezone
 */
export function getDateRange(startTime: number, endTime: number): string[] {
  const dates: string[] = []
  const start = new Date(startTime)
  const end = new Date(endTime)
  start.setHours(0, 0, 0, 0)
  end.setHours(0, 0, 0, 0)
  const cur = new Date(start)
  while (cur <= end) {
    dates.push(formatDate(cur))
    cur.setDate(cur.getDate() + 1)
  }
  return dates
}

/**
 * Validate date range
 */
export function validateDateRange(startDate: Date, endDate: Date): { valid: boolean; error?: string } {
  // Start date must be less than end date
  if (startDate >= endDate) {
    return { valid: false, error: 'Start date must be less than end date' }
  }

  return { valid: true }
}
/**
 * Formatting utility functions
 */

/**
 * Format date
 */
export function formatDate(date: string | Date, format = 'YYYY-MM-DD HH:mm:ss'): string {
  if (!date) return ''

  const d = new Date(date)
  const year = d.getFullYear()
  const month = String(d.getMonth() + 1).padStart(2, '0')
  const day = String(d.getDate()).padStart(2, '0')
  const hours = String(d.getHours()).padStart(2, '0')
  const minutes = String(d.getMinutes()).padStart(2, '0')
  const seconds = String(d.getSeconds()).padStart(2, '0')

  return format
    .replace('YYYY', String(year))
    .replace('MM', month)
    .replace('DD', day)
    .replace('HH', hours)
    .replace('mm', minutes)
    .replace('ss', seconds)
}

/**
 * Format file size
 */
export function formatFileSize(bytes: number): string {
  if (bytes === 0) return '0 B'

  const k = 1024
  const sizes = ['B', 'KB', 'MB', 'GB', 'TB']
  const i = Math.floor(Math.log(bytes) / Math.log(k))

  return `${(bytes / Math.pow(k, i)).toFixed(2)} ${sizes[i]}`
}

/**
 * Format number (thousands separator)
 */
export function formatNumber(num: number): string {
  return num.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',')
}

/**
 * Format token count with locale (e.g. 1,234). Handles null/undefined/NaN as '-'.
 */
export function formatTokenCount(value?: number | string | null): string {
  if (value == null) return '-'
  const num = typeof value === 'string' ? parseInt(value, 10) : Number(value)
  if (Number.isNaN(num)) return '-'
  return num.toLocaleString()
}

/**
 * Truncate text
 */
export function truncate(text: string, length: number, suffix = '...'): string {
  if (text.length <= length) return text
  return text.substring(0, length) + suffix
}
