  agent?: string
  commitUrl?: string
  createdAt?: number
  updatedAt?: number
}

export interface RepoOption {
  repoId: number
  repoName: string
}

export interface CheckpointSearchParams {
  startTime?: number
  endTime?: number
  repoIds?: number[]
  commitAuthorNames?: string[]
