/**
 * Chart palette shared by every chart (ECharts draws on canvas, so it needs hex values, not CSS vars).
 *
 * The categorical slots are the same validated palette as --session-N in assets/css/main.css
 * (light surface #ffffff, dark surface slate-900 #0f172a). Slots are assigned in fixed order,
 * never cycled: anything past slot 8 folds into the neutral "other".
 */
export type ChartMode = 'light' | 'dark'

export const CATEGORICAL: Record<ChartMode, string[]> = {
  light: ['#2a78d6', '#eb6834', '#1baf7a', '#eda100', '#e87ba4', '#008300', '#6250d6', '#e34948'],
  dark: ['#3987e5', '#d95926', '#199e70', '#c98500', '#d55181', '#008300', '#9085e9', '#e66767'],
}
export const OTHER: Record<ChartMode, string> = { light: '#94a3b8', dark: '#64748b' }

/** Single-hue sequential ramp (blue), near-zero first. Dark mode uses its own steps so low values recede into the dark surface. */
export const SEQUENTIAL: Record<ChartMode, string[]> = {
  light: ['#cde2fb', '#9ec5f4', '#6da7ec', '#3987e5', '#256abf', '#184f95', '#0d366b'],
  dark: ['#104281', '#184f95', '#256abf', '#2a78d6', '#5598e7', '#86b6ef', '#cde2fb'],
}

export interface ChartTheme {
  mode: ChartMode
  surface: string
  text: string
  subText: string
  axisLine: string
  splitLine: string
  tooltipBg: string
  tooltipBorder: string
  /** AI-written lines: the emphasized series */
  ai: string
  /** Human-written lines: recessive neutral, so the AI share reads first */
  human: string
  /** Input tokens / output tokens */
  input: string
  output: string
  sequential: string[]
}

export function chartTheme(mode: ChartMode): ChartTheme {
  const dark = mode === 'dark'
  return {
    mode,
    surface: dark ? '#0f172a' : '#ffffff',
    text: dark ? '#e2e8f0' : '#334155',
    subText: dark ? '#94a3b8' : '#64748b',
    axisLine: dark ? '#334155' : '#e2e8f0',
    splitLine: dark ? '#1e293b' : '#f1f5f9',
    tooltipBg: dark ? '#1e293b' : '#ffffff',
    tooltipBorder: dark ? '#334155' : '#e2e8f0',
    ai: CATEGORICAL[mode][0]!,
    human: OTHER[mode],
    input: CATEGORICAL[mode][0]!,
    output: CATEGORICAL[mode][1]!,
    sequential: SEQUENTIAL[mode],
  }
}

// ---- Agents ----------------------------------------------------------------

/** ECharts symbol per agent: a second channel so agent identity never relies on color alone */
export type AgentSymbol = 'circle' | 'rect' | 'triangle' | 'diamond' | 'pin' | 'arrow' | 'roundRect'

interface AgentStyle {
  /** 0-based categorical slot, or -1 for "other" */
  slot: number
  symbol: AgentSymbol
}

/** Fixed agent -> slot/symbol table (matched by lowercase substring), so an agent keeps its look whatever is filtered */
const AGENT_STYLES: [match: string, style: AgentStyle][] = [
  ['claude', { slot: 1, symbol: 'circle' }],
  ['codex', { slot: 2, symbol: 'rect' }],
  ['gemini', { slot: 0, symbol: 'triangle' }],
  ['copilot', { slot: 3, symbol: 'diamond' }],
  ['opencode', { slot: 4, symbol: 'pin' }],
  ['pi', { slot: 5, symbol: 'arrow' }],
  ['cursor', { slot: 6, symbol: 'roundRect' }],
  ['droid', { slot: 7, symbol: 'triangle' }],
]

function agentStyle(agent?: string | null): AgentStyle {
  const name = (agent || '').toLowerCase()
  if (name === 'pi') return AGENT_STYLES.find(([m]) => m === 'pi')![1]
  for (const [match, style] of AGENT_STYLES) {
    if (match !== 'pi' && name.includes(match)) return style
  }
  return { slot: -1, symbol: 'circle' }
}

export function agentColor(agent: string | null | undefined, mode: ChartMode): string {
  const { slot } = agentStyle(agent)
  return slot >= 0 ? CATEGORICAL[mode][slot]! : OTHER[mode]
}

export function agentSymbol(agent: string | null | undefined): AgentSymbol {
  return agentStyle(agent).symbol
}

/** Inline SVG path (viewBox 0 0 12 12) for legends drawn in HTML, mirroring the ECharts symbol */
export function agentSymbolSvg(agent: string | null | undefined): string {
  switch (agentSymbol(agent)) {
    case 'rect': return 'M2 2h8v8H2z'
    case 'roundRect': return 'M4 2h4a2 2 0 0 1 2 2v4a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2z'
    case 'triangle': return 'M6 1.5l5 9H1z'
    case 'diamond': return 'M6 1l5 5-5 5-5-5z'
    case 'pin': return 'M6 1a4 4 0 0 1 4 4c0 3-4 6.5-4 6.5S2 8 2 5a4 4 0 0 1 4-4z'
    case 'arrow': return 'M6 1l4.5 10L6 8.5 1.5 11z'
    default: return 'M6 1.5a4.5 4.5 0 1 1 0 9a4.5 4.5 0 1 1 0-9z'
  }
}

/**
 * Reactive chart theme following the color mode, plus the ECharts pieces every chart shares
 * (recessive axes, hairline solid grid, themed tooltip).
 */
import { chartTheme, type ChartTheme } from '~/shared/utils/chart-palette'

export function useChartTheme() {
  const colorMode = useColorMode()
  const theme = computed<ChartTheme>(() => chartTheme(colorMode.value === 'dark' ? 'dark' : 'light'))

  const tooltip = computed(() => ({
    backgroundColor: theme.value.tooltipBg,
    borderColor: theme.value.tooltipBorder,
    borderWidth: 1,
    padding: [8, 10],
    textStyle: { color: theme.value.text, fontSize: 12 },
    extraCssText: 'box-shadow: 0 4px 12px rgb(0 0 0 / 0.12); border-radius: 6px;',
  }))

  /** Category/time axis along the bottom */
  const xAxisBase = computed(() => ({
    axisLine: { lineStyle: { color: theme.value.axisLine } },
    axisTick: { show: false },
    axisLabel: { color: theme.value.subText, fontSize: 11, hideOverlap: true },
    splitLine: { show: false },
  }))

  /** Value axis: no line, solid hairline grid */
  const yAxisBase = computed(() => ({
    axisLine: { show: false },
    axisTick: { show: false },
    axisLabel: { color: theme.value.subText, fontSize: 11 },
    splitLine: { lineStyle: { color: theme.value.splitLine, type: 'solid' as const } },
    nameTextStyle: { color: theme.value.subText, fontSize: 11 },
  }))

  return { theme, tooltip, xAxisBase, yAxisBase }
}

/**
 * Overview module - API client
 */
import { $adminApi } from '~/api/admin-api-client'
import type { AnalyticsResponse } from '../types/analytics.types'

export const overviewApi = {
  /** Every checkpoint in [startTime, endTime] with its session aggregates (max 180 days) */
  async getAnalytics(params: { startTime: number; endTime: number }) {
    return $adminApi<AnalyticsResponse>('/overview/analytics', {
      method: 'GET',
      query: params,
    })
  },
}

/**
 * Pure aggregations over analytics rows. Everything is computed in the browser's timezone,
 * so "per day" and "hour of day" match what the user reads on the axes.
 */
import { formatDate } from '~/shared/utils/date'
import type { AnalyticsRow, FilterDim, OverviewFilters } from '../types/analytics.types'

export const UNKNOWN = 'Unknown'

export function dimValue(row: AnalyticsRow, dim: FilterDim): string {
  switch (dim) {
    case 'repo': return row.repoName || UNKNOWN
    case 'author': return row.commitAuthorName || UNKNOWN
    case 'agent': return row.agent || UNKNOWN
  }
}

/** Apply every active filter except `except` (crossfilter: a dimension's own chart still shows its siblings) */
export function applyFilters(rows: AnalyticsRow[], filters: OverviewFilters, except?: FilterDim): AnalyticsRow[] {
  const active = (Object.keys(filters) as FilterDim[]).filter((d) => d !== except && filters[d] != null)
  if (!active.length) return rows
  return rows.filter((r) => active.every((d) => dimValue(r, d) === filters[d]))
}

/** Tokens spent: per-session input+output when recorded, else the checkpoint's cumulative total */
export function rowTokens(r: AnalyticsRow): number {
  const s = (r.inputTokens ?? 0) + (r.outputTokens ?? 0)
  return s > 0 ? s : (r.tokenUsage ?? 0)
}

export function hasAttribution(r: AnalyticsRow): boolean {
  return r.agentLines != null
}

/** Committed lines a human wrote (added, or rewrote from the agent's output) */
export function humanLines(r: AnalyticsRow): number {
  return (r.humanAdded ?? 0) + (r.humanModified ?? 0)
}

export interface Totals {
  checkpoints: number
  repos: number
  authors: number
  tokens: number
  inputTokens: number
  outputTokens: number
  agentLines: number
  humanLines: number
  /** Checkpoints carrying line attribution */
  attributed: number
  /** Agent share of attributed committed lines, 0..1, null when nothing is attributed */
  aiShare: number | null
}

export function totals(rows: AnalyticsRow[]): Totals {
  const repos = new Set<string>()
  const authors = new Set<string>()
  let tokens = 0, inputTokens = 0, outputTokens = 0, agent = 0, human = 0, attributed = 0
  for (const r of rows) {
    repos.add(dimValue(r, 'repo'))
    if (r.commitAuthorName) authors.add(r.commitAuthorName)
    tokens += rowTokens(r)
    inputTokens += r.inputTokens ?? 0
    outputTokens += r.outputTokens ?? 0
    if (hasAttribution(r)) {
      attributed++
      agent += r.agentLines ?? 0
      human += humanLines(r)
    }
  }
  return {
    checkpoints: rows.length,
    repos: repos.size,
    authors: authors.size,
    tokens,
    inputTokens,
    outputTokens,
    agentLines: agent,
    humanLines: human,
    attributed,
    aiShare: agent + human > 0 ? agent / (agent + human) : null,
  }
}

export interface DayBucket {
  date: string
  checkpoints: number
  agentLines: number
  humanLines: number
  inputTokens: number
  outputTokens: number
  /** Tokens of checkpoints without a per-session split */
  otherTokens: number
  authors: Set<string>
  repos: Set<string>
}

/** One bucket per calendar day in `dates`, in order (days without data stay at zero) */
export function byDay(rows: AnalyticsRow[], dates: string[]): DayBucket[] {
  const map = new Map<string, DayBucket>(dates.map((date) => [date, {
    date, checkpoints: 0, agentLines: 0, humanLines: 0, inputTokens: 0, outputTokens: 0, otherTokens: 0,
    authors: new Set(), repos: new Set(),
  }]))
  for (const r of rows) {
    const b = map.get(formatDate(new Date(r.commitTime)))
    if (!b) continue
    b.checkpoints++
    b.repos.add(dimValue(r, 'repo'))
    if (r.commitAuthorName) b.authors.add(r.commitAuthorName)
    if (hasAttribution(r)) {
      b.agentLines += r.agentLines ?? 0
      b.humanLines += humanLines(r)
    }
    if ((r.inputTokens ?? 0) + (r.outputTokens ?? 0) > 0) {
      b.inputTokens += r.inputTokens ?? 0
      b.outputTokens += r.outputTokens ?? 0
    } else {
      b.otherTokens += r.tokenUsage ?? 0
    }
  }
  return dates.map((d) => map.get(d)!)
}

export interface GroupStat {
  key: string
  checkpoints: number
  agentLines: number
  humanLines: number
  tokens: number
}

export function groupBy(rows: AnalyticsRow[], dim: FilterDim): GroupStat[] {
  const map = new Map<string, GroupStat>()
  for (const r of rows) {
    const key = dimValue(r, dim)
    let g = map.get(key)
    if (!g) map.set(key, (g = { key, checkpoints: 0, agentLines: 0, humanLines: 0, tokens: 0 }))
    g.checkpoints++
    g.tokens += rowTokens(r)
    if (hasAttribution(r)) {
      g.agentLines += r.agentLines ?? 0
      g.humanLines += humanLines(r)
    }
  }
  return [...map.values()]
}

/** Checkpoint counts per [weekday (0 = Monday), hour] */
export function punchCard(rows: AnalyticsRow[]): number[][] {
  const grid = Array.from({ length: 7 }, () => new Array<number>(24).fill(0))
  for (const r of rows) {
    const d = new Date(r.commitTime)
    grid[(d.getDay() + 6) % 7]![d.getHours()]!++
  }
  return grid
}

/** Relative change, null when there is no base to compare to */
export function relativeChange(current: number, previous: number): number | null {
  if (!previous) return null
  return (current - previous) / previous
}

/**
 * Overview state: date range + cross-filters, both mirrored in the URL so a view can be shared
 * and survives a reload. One request fetches the selected period and the one before it; every
 * chart is then derived client-side from the same rows, so filters apply to the whole page at once.
 */
import { overviewApi } from '../api/overview.api'
import { applyFilters } from '../utils/aggregate'
import type { AnalyticsRow, FilterDim, OverviewFilters, RangePreset } from '../types/analytics.types'
import { formatDate, getDateRange } from '~/shared/utils/date'

const PRESET_DAYS: Record<Exclude<RangePreset, 'custom'>, number> = { '7d': 7, '14d': 14, '30d': 30, '90d': 90 }
export const MAX_RANGE_DAYS = 90
const DAY_MS = 24 * 60 * 60 * 1000
const DIMS: FilterDim[] = ['repo', 'author', 'agent']

function startOfDay(d: Date): number {
  const x = new Date(d)
  x.setHours(0, 0, 0, 0)
  return x.getTime()
}
function endOfDay(d: Date): number {
  const x = new Date(d)
  x.setHours(23, 59, 59, 999)
  return x.getTime()
}
/** YYYY-MM-DD as a local date (new Date('YYYY-MM-DD') would be UTC) */
function parseLocalDate(s: string): Date | null {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s)
  return m ? new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3])) : null
}
function isPreset(v: unknown): v is RangePreset {
  return v === 'custom' || (typeof v === 'string' && v in PRESET_DAYS)
}

export function useOverviewAnalytics() {
  const route = useRoute()
  const router = useRouter()

  // ---- state from URL ----------------------------------------------------------
  const q = route.query
  const preset = ref<RangePreset>(isPreset(q.range) ? q.range : '14d')
  const customFrom = ref<string>(typeof q.from === 'string' ? q.from : formatDate(new Date(Date.now() - 13 * DAY_MS)))
  const customTo = ref<string>(typeof q.to === 'string' ? q.to : formatDate(new Date()))
  const filters = reactive<OverviewFilters>({
    repo: typeof q.repo === 'string' ? q.repo : null,
    author: typeof q.author === 'string' ? q.author : null,
    agent: typeof q.agent === 'string' ? q.agent : null,
  })

  watch([preset, customFrom, customTo, () => ({ ...filters })], () => {
    const query: Record<string, string> = { range: preset.value }
    if (preset.value === 'custom') {
      query.from = customFrom.value
      query.to = customTo.value
    }
    for (const d of DIMS) if (filters[d] != null) query[d] = filters[d]!
    if (JSON.stringify(query) !== JSON.stringify(route.query)) router.replace({ query })
  }, { deep: true })

  // ---- range -------------------------------------------------------------------
  const rangeError = ref<string | null>(null)
  const range = computed<{ start: number; end: number } | null>(() => {
    rangeError.value = null
    if (preset.value !== 'custom') {
      const today = new Date()
      const start = new Date(today)
      start.setDate(start.getDate() - (PRESET_DAYS[preset.value] - 1))
      return { start: startOfDay(start), end: endOfDay(today) }
    }
    const from = parseLocalDate(customFrom.value)
    const to = parseLocalDate(customTo.value)
    if (!from || !to) {
      rangeError.value = 'Pick a start and an end date'
      return null
    }
    if (from > to) {
      rangeError.value = 'The start date must be before the end date'
      return null
    }
    const start = startOfDay(from)
    const end = endOfDay(to)
    if (end - start > MAX_RANGE_DAYS * DAY_MS) {
      rangeError.value = `The range can be at most ${MAX_RANGE_DAYS} days`
      return null
    }
    return { start, end }
  })
  /** The period just before, same length, for comparisons */
  const previousRange = computed(() => {
    const r = range.value
    if (!r) return null
    const len = r.end - r.start + 1
    return { start: r.start - len, end: r.start - 1 }
  })
  const dates = computed(() => (range.value ? getDateRange(range.value.start, range.value.end) : []))

  // ---- data --------------------------------------------------------------------
  const rows = ref<AnalyticsRow[]>([])
  const truncated = ref(false)
  const pending = ref(false)
  const loaded = ref(false)
  const error = ref<string | null>(null)
  let seq = 0

  async function fetchRows() {
    const r = range.value
    const p = previousRange.value
    if (!r || !p) return
    const mySeq = ++seq
    pending.value = true
    error.value = null
    try {
      const res = await overviewApi.getAnalytics({ startTime: p.start, endTime: r.end })
      if (mySeq !== seq) return
      rows.value = res.rows ?? []
      truncated.value = !!res.truncated
      loaded.value = true
    } catch (e: any) {
      if (mySeq === seq) error.value = e?.data?.message || e?.message || 'Failed to load analytics'
    } finally {
      if (mySeq === seq) pending.value = false
    }
  }
  watch(range, fetchRows, { immediate: true, deep: true })

  const inRange = (r: AnalyticsRow, span: { start: number; end: number } | null) =>
    !!span && r.commitTime >= span.start && r.commitTime <= span.end

  /** Current period, no filters: the source for filter options */
  const periodRows = computed(() => rows.value.filter((r) => inRange(r, range.value)))
  const previousPeriodRows = computed(() => rows.value.filter((r) => inRange(r, previousRange.value)))
  /** Current period with every filter */
  const current = computed(() => applyFilters(periodRows.value, filters))
  const previous = computed(() => applyFilters(previousPeriodRows.value, filters))
  /** Current period with every filter except one dimension's own (for that dimension's chart / legend) */
  function currentExcept(dim: FilterDim) {
    return applyFilters(periodRows.value, filters, dim)
  }

  // ---- actions -----------------------------------------------------------------
  function setPreset(p: RangePreset) {
    preset.value = p
  }
  /** Set a filter; selecting the active value again clears it */
  function toggleFilter(dim: FilterDim, value: string | null) {
    filters[dim] = value == null || filters[dim] === value ? null : value
  }
  function clearFilters() {
    for (const d of DIMS) filters[d] = null
  }
  const hasFilters = computed(() => DIMS.some((d) => filters[d] != null))

  return {
    preset,
    customFrom,
    customTo,
    setPreset,
    range,
    rangeError,
    dates,
    filters,
    toggleFilter,
    clearFilters,
    hasFilters,
    periodRows,
    current,
    previous,
    currentExcept,
    truncated,
    pending,
    loaded,
    error,
    refresh: fetchRows,
  }
}

