export interface FolderAiStat {
  /** Files under the folder touched by at least one AI session */
  ai: number
  total: number
}

/** Per folder (keyed by fullPath): how many of the files below it AI sessions touched */
export function folderAiStats(nodes: FileTreeNode[], sessionCountByPath: Map<string, number>): Map<string, FolderAiStat> {
  const out = new Map<string, FolderAiStat>()
  function walk(list: FileTreeNode[]): FolderAiStat {
    const acc: FolderAiStat = { ai: 0, total: 0 }
    for (const n of list) {
      if (n.isFile) {
        acc.total++
        if ((sessionCountByPath.get(n.fullPath) ?? 0) > 0) acc.ai++
      } else {
        const s = walk(n.children)
        out.set(n.fullPath, s)
        acc.ai += s.ai
        acc.total += s.total
      }
    }
    return acc
  }
  walk(nodes)
  return out
}
